function makeSeed(byte: number): Uint8Array {
    const seed = new Uint8Array(32);
    seed.fill(byte);
    return seed;
}

async function loadFixedSigners() {
    return await Promise.all([
        createKeyPairSignerFromPrivateKeyBytes(makeSeed(0x01)), // payer
        createKeyPairSignerFromPrivateKeyBytes(makeSeed(0x02)), // operator / rentPayer
        createKeyPairSignerFromPrivateKeyBytes(makeSeed(0x03)), // payee
        createKeyPairSignerFromPrivateKeyBytes(makeSeed(0x04)), // authorized (session) signer
        createKeyPairSignerFromPrivateKeyBytes(makeSeed(0x05)), // merchant
    ]);
}

