describe('buildSettleAndSealInstructions', () => {
    test('voucher-less variant: golden accounts and [disc=4][hasVoucher=0] data', async () => {
        const [, , , , merchant] = await loadFixedSigners();

        const out = buildSettleAndSealInstructions({
            channelId: CHANNEL_ID,
            merchantSigner: merchant,
        });
        expect(out.requiresEd25519Precompile).toBe(false);
        expect(out.instructions).toHaveLength(1);

        const ix = out.instructions[0]!;
        expect(ix.programAddress).toBe(PAYMENT_CHANNELS_PROGRAM_ID);
        // payee (merchant, readonly signer), channel (writable), instructions sysvar (readonly)
        expect(accountTuples(ix)).toEqual([
            [MERCHANT, AccountRole.READONLY_SIGNER],
            [CHANNEL_ID, AccountRole.WRITABLE],
            [INSTRUCTIONS_SYSVAR_ADDRESS, AccountRole.READONLY],
        ]);
        expect(merchant.address).toBe(MERCHANT);

        // The voucher lives in the ed25519 precompile; settle data is just
        // [disc=4][hasVoucher=0].
        expect(hex(ix.data)).toBe('0400');
    });

    test('voucher variant: golden Ed25519 precompile bytes prepended, [disc=4][hasVoucher=1]', async () => {
        const [, , , authorized, merchant] = await loadFixedSigners();
        const signatureBytes = new Uint8Array(64).fill(0xaa);
        const signed: SignedVoucher = {
            voucher: { channelId: CHANNEL_ID, cumulativeAmount: '500', expiresAt: 1_700_000_000 },
            signature: bs58Encode(signatureBytes),
            signatureType: 'ed25519',
            signer: authorized.address,
        };

        const out = buildSettleAndSealInstructions({
            channelId: CHANNEL_ID,
            merchantSigner: merchant,
            voucher: { authorizedSigner: authorized.address, signed },
        });
        expect(out.requiresEd25519Precompile).toBe(true);
        expect(out.instructions).toHaveLength(2);

        // Precompile IX at index 0 (settle_and_seal reads the voucher from
        // the instruction immediately before it via the instructions sysvar).
        const precompile = out.instructions[0]!;
        expect(precompile.programAddress).toBe(ED25519_PROGRAM_ADDRESS);
        expect(precompile.accounts).toEqual([]);
        const precompileData = new Uint8Array(precompile.data);
        // Structural breakdown first so a golden mismatch is explainable:
        // header (16) + authorized-signer pubkey (32) + signature (64) +
        // 50-byte voucher message.
        expect(precompileData.byteLength).toBe(16 + 32 + 64 + 50);
        expect(precompileData.slice(16, 48)).toEqual(getBase58Encoder().encode(authorized.address) as Uint8Array);
        expect(precompileData.slice(48, 112)).toEqual(signatureBytes);
        expect(precompileData.slice(112)).toEqual(
            encodeVoucherMessageBytes({
                channelId: CHANNEL_ID,
                cumulativeAmount: 500n,
                expiresAt: 1_700_000_000n,
            }),
        );
        // Golden bytes for the whole precompile instruction.
        expect(hex(precompileData)).toBe(
            '01003000ffff1000ffff70003200ffff' + // header
                'ca93ac1705187071d67b83c7ff0efe8108e8ec4530575d7726879333dbdabe7c' + // authorized signer
                'aa'.repeat(64) + // signature
                '5601' + // voucher magic
                '00'.repeat(32) + // channelId (system address = 32 zero bytes)
                'f401000000000000' + // cumulativeAmount 500 (u64 LE)
                '00f1536500000000', // expiresAt 1_700_000_000 (i64 LE)
        );

        const settle = out.instructions[1]!;
        expect(settle.programAddress).toBe(PAYMENT_CHANNELS_PROGRAM_ID);
        expect(accountTuples(settle)).toEqual([
            [MERCHANT, AccountRole.READONLY_SIGNER],
            [CHANNEL_ID, AccountRole.WRITABLE],
            [INSTRUCTIONS_SYSVAR_ADDRESS, AccountRole.READONLY],
        ]);
        expect(hex(settle.data)).toBe('0401');
    });
});

