describe('buildDistributeInstruction', () => {
    test('golden 11-account header plus one writable recipient ATA per split', async () => {
        const [payer, operator, payee] = await loadFixedSigners();
        const ix = await buildDistributeInstruction({
            channelState: { channelId: CHANNEL_ID, payee: payee.address, payer: payer.address },
            mint: USDC.mainnet!,
            rentPayer: operator.address,
            splits: [
                { bps: 1000, recipient: SPLIT_RECIPIENT },
                { bps: 250, recipient: SPLIT_RECIPIENT },
            ],
            tokenProgram: TOKEN_PROGRAM,
        });
        expect(ix.programAddress).toBe(PAYMENT_CHANNELS_PROGRAM_ID);
        // Fixed header: channel, payer, rentPayer, channel ATA, payer ATA,
        // payee ATA, treasury ATA (all writable), then mint / token program /
        // event authority / self program (readonly). Tail: one writable
        // recipient ATA per split, in split order.
        expect(accountTuples(ix)).toEqual([
            [CHANNEL_ID, AccountRole.WRITABLE],
            [PAYER, AccountRole.WRITABLE],
            [OPERATOR, AccountRole.WRITABLE],
            [CHANNEL_USDC_ATA, AccountRole.WRITABLE],
            [PAYER_USDC_ATA, AccountRole.WRITABLE],
            [PAYEE_USDC_ATA, AccountRole.WRITABLE],
            [TREASURY_USDC_ATA, AccountRole.WRITABLE],
            [USDC_MAINNET, AccountRole.READONLY],
            [TOKEN_PROGRAM, AccountRole.READONLY],
            [EVENT_AUTHORITY, AccountRole.READONLY],
            [PAYMENT_CHANNELS_PROGRAM_ID, AccountRole.READONLY],
            [SPLIT_RECIPIENT_USDC_ATA, AccountRole.WRITABLE],
            [SPLIT_RECIPIENT_USDC_ATA, AccountRole.WRITABLE],
        ]);

        // [disc=7][recipients_count u32 LE][(pubkey32 + bps u16 LE) x 2]
        const data = new Uint8Array(ix.data);
        expect(data[0]).toBe(7);
        const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
        expect(view.getUint32(1, true)).toBe(2);
        expect(view.getUint16(5 + 32, true)).toBe(1000);
        expect(view.getUint16(5 + 32 + 34, true)).toBe(250);
        expect(hex(data)).toBe(
            '0702000000' +
                'f3df6c4f444efb2d860ce6dae0b568b6dadee3c402fc33edab10836490385896' + // SPLIT_RECIPIENT
                'e803' + // 1000 bps
                'f3df6c4f444efb2d860ce6dae0b568b6dadee3c402fc33edab10836490385896' +
                'fa00', // 250 bps
        );
    });

    test('zero-split distribute keeps only the 11 fixed accounts', async () => {
        const [payer, operator, payee] = await loadFixedSigners();
        const ix = await buildDistributeInstruction({
            channelState: { channelId: CHANNEL_ID, payee: payee.address, payer: payer.address },
            mint: USDC.mainnet!,
            rentPayer: operator.address,
            splits: [],
            tokenProgram: TOKEN_PROGRAM,
        });
        expect(ix.accounts).toHaveLength(11);
        expect(hex(ix.data)).toBe('0700000000'); // [disc=7][count=0]
    });
});

