// client open builder (buildOpenPaymentChannelTransaction /
// derivePaymentChannelOpen)
// ─────────────────────────────────────────────────────────────────────

/**
 * Golden instruction data for the fixed open fixture, captured from the
 * current (post-openSlot) builder:
 *   [disc=1][salt=42 u64][deposit=1_000_000 u64][gracePeriod=900 u32]
 *   [openSlot=9_042 u64][recipients vec: len=1, pubkey32 + bps=250 u16]
 * openSlot is taken from the challenge's `recentSlot` and sits between
 * gracePeriod and recipients.
 */
const OPEN_GOLDEN_DATA_HEX =
    '01' + // discriminator
    '2a00000000000000' + // salt 42 (u64 LE)
    '40420f0000000000' + // deposit 1_000_000 (u64 LE)
    '84030000' + // gracePeriod 900 (u32 LE)
    '5223000000000000' + // openSlot 9_042 (u64 LE) — the challenged recentSlot
    '01000000' + // recipients vec length
    'f3df6c4f444efb2d860ce6dae0b568b6dadee3c402fc33edab10836490385896' + // SPLIT_RECIPIENT
    'fa00'; // 250 bps

/** Channel PDA for the fixed fixture (payer/payee/mint/authorized/salt=42/openSlot=9042). */
const OPEN_GOLDEN_CHANNEL = '9dcDepjEQ1UcwLYqpaTSFQZqxYeMq9cMsmL2541HdKjV';
/** ATA(channel PDA, USDC mainnet, SPL Token). */
const OPEN_GOLDEN_CHANNEL_ATA = 'AKc4oGBp3CCQbS9BDgaf3R5UKPHgh5o6iSrYjpxoe9SN';

function openChallengeRequest(overrides: Record<string, unknown> = {}): SessionRequest {
    return {
        amount: '100',
        currency: 'USDC',
        methodDetails: {
            channelProgram: PAYMENT_CHANNELS_PROGRAM_ID.toString(),
            // Gasless flow: the operator co-signs as fee payer and rentPayer.
            feePayer: true,
            feePayerKey: OPERATOR,
            gracePeriodSeconds: 900,
            network: 'mainnet',
            recentBlockhash: CHALLENGED_BLOCKHASH,
            recentSlot: CHALLENGED_SLOT.toString(),
            ...overrides,
        },
        recipient: PAYEE,
    } as unknown as SessionRequest;
}

async function buildFixtureOpen() {
    const [payer] = await loadFixedSigners();
    return await buildOpenPaymentChannelTransaction({
        authorizedSigner: AUTHORIZED,
        deposit: 1_000_000n,
        gracePeriod: 900,
        recipients: [{ bps: 250, recipient: SPLIT_RECIPIENT }],
        request: openChallengeRequest(),
        salt: 42n,
        signer: payer,
    });
}

interface TestCompiledMessage {
    header: {
        numReadonlyNonSignerAccounts: number;
        numReadonlySignerAccounts: number;
        numSignerAccounts: number;
    };
    instructions: readonly {
        accountIndices?: readonly number[];
        data?: Uint8Array;
        programAddressIndex: number;
    }[];
    lifetimeToken?: string;
    staticAccounts: readonly string[];
}

function decodeOpenMessage(transaction: string): TestCompiledMessage {
    const decoded = getTransactionDecoder().decode(getBase64Codec().encode(transaction));
    return getCompiledTransactionMessageDecoder().decode(decoded.messageBytes) as unknown as TestCompiledMessage;
}

describe('client open instruction builder', () => {
    test('open instruction data bytes match the golden buffer (salt/deposit/gracePeriod/openSlot/splits)', async () => {
        const open = await buildFixtureOpen();
        const message = decodeOpenMessage(open.transaction);
        expect(message.instructions).toHaveLength(1);
        const ix = message.instructions[0]!;
        expect(message.staticAccounts[ix.programAddressIndex]).toBe(PAYMENT_CHANNELS_PROGRAM_ID.toString());
        expect(hex(ix.data!)).toBe(OPEN_GOLDEN_DATA_HEX);

        // Decode the golden back into fields so a byte diff explains itself.
        const decoded = getOpenInstructionDataDecoder().decode(ix.data!);
        expect(decoded.discriminator).toBe(1);
        expect(decoded.openArgs.salt).toBe(42n);
        expect(decoded.openArgs.deposit).toBe(1_000_000n);
        expect(decoded.openArgs.gracePeriod).toBe(900);
        expect(decoded.openArgs.openSlot).toBe(CHALLENGED_SLOT);
        expect(decoded.openArgs.recipients).toEqual([{ bps: 250, recipient: SPLIT_RECIPIENT }]);

        // The returned open fields echo the encoded instruction.
        expect(open.deposit).toBe('1000000');
        expect(open.gracePeriod).toBe(900);
        expect(open.mint).toBe(USDC_MAINNET);
        expect(open.openSlot).toBe(CHALLENGED_SLOT.toString());
        expect(open.payee).toBe(PAYEE);
        expect(open.payer).toBe(PAYER);
        expect(open.salt).toBe('42');
    });

    test('open instruction account list is in canonical order with the operator as rentPayer', async () => {
        const open = await buildFixtureOpen();
        const message = decodeOpenMessage(open.transaction);
        const ix = message.instructions[0]!;

        // Slot layout enforced by verifyOpenTx: 0 payer, 1 rentPayer,
        // 2 payee, 3 mint, 4 authorizedSigner, 5 channel, 6 payer ATA,
        // 7 channel ATA, 8 token program, then system/rent/ATA-program/
        // event-authority/self-program.
        const accounts = (ix.accountIndices ?? []).map(index => message.staticAccounts[index]);
        expect(accounts).toEqual([
            PAYER,
            OPERATOR, // rentPayer = operator / fee payer
            PAYEE,
            USDC_MAINNET,
            AUTHORIZED,
            OPEN_GOLDEN_CHANNEL,
            PAYER_USDC_ATA,
            OPEN_GOLDEN_CHANNEL_ATA,
            TOKEN_PROGRAM,
            SYSTEM_PROGRAM,
            RENT_SYSVAR,
            ASSOCIATED_TOKEN_PROGRAM,
            EVENT_AUTHORITY,
            PAYMENT_CHANNELS_PROGRAM_ID.toString(),
        ]);

        // The compiled message pins the writable/signer flags: the operator
        // (fee payer) and payer are the two writable signers, the payer ATA,
        // channel PDA, and channel ATA are the writable non-signers, and the
        // remaining 9 accounts are readonly.
        expect(message.lifetimeToken).toBe(CHALLENGED_BLOCKHASH);
        expect(message.header).toEqual({
            numReadonlyNonSignerAccounts: 9,
            numReadonlySignerAccounts: 0,
            numSignerAccounts: 2,
        });
        expect(message.staticAccounts).toEqual([
            OPERATOR, // fee payer (writable signer)
            PAYER, // writable signer
            PAYER_USDC_ATA, // writable
            OPEN_GOLDEN_CHANNEL, // writable
            OPEN_GOLDEN_CHANNEL_ATA, // writable
            SYSTEM_PROGRAM,
            EVENT_AUTHORITY,
            ASSOCIATED_TOKEN_PROGRAM,
            PAYMENT_CHANNELS_PROGRAM_ID.toString(),
            AUTHORIZED,
            USDC_MAINNET,
            PAYEE,
            RENT_SYSVAR,
            TOKEN_PROGRAM,
        ]);

        // Partially signed: the payer has signed; the operator slot is left
        // for the server to co-sign before broadcast.
        const decoded = getTransactionDecoder().decode(getBase64Codec().encode(open.transaction));
        const signatures = decoded.signatures as Readonly<Record<string, Uint8Array | null>>;
        expect(Object.keys(signatures)).toEqual([OPERATOR, PAYER]);
        const payerSignature = signatures[PAYER];
        expect(payerSignature && payerSignature.some(byte => byte !== 0)).toBe(true);
        const operatorSignature = signatures[OPERATOR];
        expect(operatorSignature === null || operatorSignature.every(byte => byte === 0)).toBe(true);
    });

    test('channel PDA derives from [channel, payer, payee, mint, authorizedSigner, salt, openSlot]', async () => {
        const derived = await derivePaymentChannelOpen({
            authorizedSigner: AUTHORIZED,
            deposit: 1_000_000n,
            payer: PAYER,
            request: openChallengeRequest(),
            salt: 42n,
        });
        expect(derived.channelId).toBe(OPEN_GOLDEN_CHANNEL);
        expect(derived.openSlot).toBe(CHALLENGED_SLOT.toString());

        const [recomputed] = await getProgramDerivedAddress({
            programAddress: PAYMENT_CHANNELS_PROGRAM_ID,
            seeds: [
                getUtf8Encoder().encode('channel'),
                getAddressEncoder().encode(address(PAYER)),
                getAddressEncoder().encode(address(PAYEE)),
                getAddressEncoder().encode(address(USDC_MAINNET)),
                getAddressEncoder().encode(address(AUTHORIZED)),
                getU64Encoder().encode(42n),
                getU64Encoder().encode(CHALLENGED_SLOT),
            ],
        });
        expect(recomputed).toBe(OPEN_GOLDEN_CHANNEL);

        // The channel token account in the built transaction is the canonical
        // ATA of that PDA.
        const [channelAta] = await findAssociatedTokenPda({
            mint: address(USDC_MAINNET),
            owner: address(OPEN_GOLDEN_CHANNEL),
            tokenProgram: address(TOKEN_PROGRAM),
        });
        expect(channelAta).toBe(OPEN_GOLDEN_CHANNEL_ATA);
    });

    test('openSlot is a PDA seed: a different (rewound) openSlot yields a different channel', async () => {
        const rewound = await derivePaymentChannelOpen({
            authorizedSigner: AUTHORIZED,
            deposit: 1_000_000n,
            openSlot: CHALLENGED_SLOT - 1n,
            payer: PAYER,
            request: openChallengeRequest(),
            salt: 42n,
        });
        expect(rewound.openSlot).toBe((CHALLENGED_SLOT - 1n).toString());
        expect(rewound.channelId).not.toBe(OPEN_GOLDEN_CHANNEL);
    });

    test('a PYUSD challenge derives Token-2022 accounts by default', async () => {
        const [payer] = await loadFixedSigners();
        const open = await buildOpenPaymentChannelTransaction({
            authorizedSigner: AUTHORIZED,
            deposit: 1_000_000n,
            gracePeriod: 900,
            request: {
                ...(openChallengeRequest() as unknown as Record<string, unknown>),
                currency: 'PYUSD',
            } as unknown as SessionRequest,
            salt: 42n,
            signer: payer,
        });
        expect(open.mint).toBe(PYUSD.mainnet);

        const message = decodeOpenMessage(open.transaction);
        expect(message.staticAccounts).toContain(TOKEN_2022_PROGRAM);
        expect(message.staticAccounts).not.toContain(TOKEN_PROGRAM);

        const [payerTokenAccount] = await findAssociatedTokenPda({
            mint: address(PYUSD.mainnet!),
            owner: payer.address,
            tokenProgram: address(TOKEN_2022_PROGRAM),
        });
        expect(message.staticAccounts).toContain(payerTokenAccount);
    });
});
